def test_matches_pairwise_definition(self):
    self.assertEqual(find_overlaps(sample(600, 3)), pairwise(sample(600, 3)))

def test_matches_pairwise_definition_on_awkward_inputs(self):
    # Short spans so starts and ends collide constantly, plus empty
    # bookings, which clash with anything strictly containing them.
    for seed in range(200):
        rng = random.Random(seed)
        bookings = [
            Booking(f"b{i:02d}", f"r{rng.randrange(2)}", start, start + rng.choice([0, 0, 1, 2, 4]))
            for i in range(rng.randrange(20))
            for start in [rng.randrange(10)]
        ]
        self.assertEqual(find_overlaps(bookings), pairwise(bookings), f"seed {seed}")

